 h=len(grid); w=len(grid[0]); out=[[0]*w for _ in range(h)]
 for r in range(h):
  for c in range(w):
   if grid[r][c]==6:
    for i in range(r-1,r+2):
     for j in range(c-1,c+2):
      if 0<=i<h and 0<=j<w: out[i][j]=6 if (i,j)==(r,c) else 2
    return out
